import io
import re
import wave

ENGINES = {
    "standard": {"per_1m_chars": 4.0, "free_chars": 5_000_000},
    "neural": {"per_1m_chars": 16.0, "free_chars": 1_000_000},
    "long-form": {"per_1m_chars": 100.0, "free_chars": 500_000},
    "generative": {"per_1m_chars": 30.0, "free_chars": 100_000},
}

SYNC_TOTAL, SYNC_BILLED = 6_000, 3_000
ASYNC_TOTAL, ASYNC_BILLED = 200_000, 100_000

TAG = re.compile(r"<[^>]+>")


def total_characters(text):
    return len(text)


def billed_characters(text, text_type="text"):
    if text_type == "text":
        return len(text)
    if text_type == "ssml":
        return len(TAG.sub("", text))
    raise ValueError(f"unknown text type {text_type!r}")


def monthly_cost(chars, engine):
    if engine not in ENGINES:
        raise ValueError(f"unknown engine {engine!r}")
    billable = max(0, chars - ENGINES[engine]["free_chars"])
    return billable / 1_000_000 * ENGINES[engine]["per_1m_chars"]


def plan_request(text, voice, engine, voices, text_type="text"):
    if engine not in ENGINES:
        raise ValueError(f"unknown engine {engine!r}")
    supported = voices.get(voice)
    if supported is None:
        raise ValueError(f"unknown voice {voice!r}")
    if engine not in supported:
        raise ValueError(f"voice {voice!r} does not support the {engine!r} engine")
    total = total_characters(text)
    billed = billed_characters(text, text_type)
    if total > ASYNC_TOTAL or billed > ASYNC_BILLED:
        raise ValueError(
            f"{total} total / {billed} billed characters exceeds the asynchronous "
            f"limit of {ASYNC_TOTAL} / {ASYNC_BILLED}")
    synchronous = total <= SYNC_TOTAL and billed <= SYNC_BILLED
    return {
        "api": "synthesize_speech" if synchronous else "start_speech_synthesis_task",
        "total": total,
        "billed": billed,
        "cost": monthly_cost(billed, engine),
    }


def wrap_pcm(raw, sample_rate=16000):
    buffer = io.BytesIO()
    with wave.open(buffer, "wb") as writer:
        writer.setnchannels(1)
        writer.setsampwidth(2)
        writer.setframerate(sample_rate)
        writer.writeframes(raw)
    return buffer.getvalue()
